import { describe, expect, it } from 'vitest'
import { curveFor, takerPrice, withLift } from './curve'
import {
  averageUnwindWeight,
  heldLift,
  liftedFlatOrderNgn,
  liftLimitNgn,
  unwindFullNgn,
} from './unwind'
import cases from './unwindParity.json'

// Generated by tests/unwind_parity.rs from the bot's own unwind::shift,
// average_weight, Curve::with_lift and lifted_flat_price. On the curve the
// ask is floored on the signed order and the venue fee added after, so the
// panel's lifted curve must price exactly what the taker realizes; on a flat
// price the fixture pins the signed order itself.
type Case = {
  knobs: {
    share: number
    cap_ngn: number
    min_gain_ngn: number
    start_pct: number
  }
  cost: number
  feed_mid: number
  reference: { mid: number; half_range_bps: number }
  spread_bps: number
  fee_bps: number
  curve: { start_below_mid: number; end_above_buy: number; shape: number }
  stretch: [number, number]
  full_ngn: number
  gain: number
  average_weight: number
  bid: number
  ask: number
  plain_ask: number
  flat_bid: number
  flat_ask: number
}

const close = (got: number, want: number) =>
  expect(Math.abs(got - want)).toBeLessThanOrEqual(
    Math.max(Math.abs(want), 1) * 1e-9
  )

describe('the panel lifts the curve as the bot does', () => {
  it.each((cases as Case[]).map((c, i) => [i, c] as const))(
    'case %i',
    (_, c) => {
      const full = unwindFullNgn(c.knobs, {
        cost: c.cost,
        feed_mid: c.feed_mid,
      })
      close(full, c.full_ngn)
      const [f0, f1] = c.stretch
      close(averageUnwindWeight(f0, f1, c.knobs.start_pct), c.average_weight)
      const plain = curveFor(
        c.reference,
        c.spread_bps + c.fee_bps,
        c.curve,
        c.spread_bps
      )!
      const lifted = withLift(plain, {
        fullNgn: full,
        startPct: c.knobs.start_pct,
        costNgn: c.cost,
      })
      close(takerPrice(lifted, true, f0, f1), c.bid)
      close(takerPrice(lifted, false, f0, f1), c.ask)
      close(takerPrice(plain, false, f0, f1), c.plain_ask)
      // The same lift on the flat signed order around the feed.
      const half = c.spread_bps / 10_000
      const flat = heldLift(
        { fullNgn: full, startPct: c.knobs.start_pct, costNgn: c.cost },
        liftLimitNgn(c.spread_bps, c.feed_mid, c.knobs.start_pct)
      )
      const order = (buys: boolean) =>
        buys ? c.feed_mid / (1 - half) : c.feed_mid / (1 + half)
      const lifted_ = (buys: boolean) =>
        flat
          ? liftedFlatOrderNgn(order(buys), buys, flat, c.feed_mid, f0, f1)
          : order(buys)
      close(lifted_(true), c.flat_bid)
      close(lifted_(false), c.flat_ask)
    }
  )
})
